import{_ as i,C as a,c as e,o,j as l,G as t,b as r,a0 as n,a as s,w as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Essere un grande giocatore di squadra","description":"","frontmatter":{},"headers":[],"relativePath":"it/education/team-player/index.md","filePath":"it/education/team-player/index.md"}');const p=i({name:"it/education/team-player/index.md"},[["render",function(i,u,p,m,h,g){const f=a("AdBanner"),q=a("Mermaid"),b=a("AdInArticle");return o(),e("div",null,[u[1]||(u[1]=l("h1",{id:"essere-un-grande-giocatore-di-squadra",tabindex:"-1"},[s("Essere un grande giocatore di squadra "),l("a",{class:"header-anchor",href:"#essere-un-grande-giocatore-di-squadra","aria-label":'Permalink to "Essere un grande giocatore di squadra"'},"​")],-1)),t(f),u[2]||(u[2]=l("p",null,"La boccia si gioca spesso a squadre: in doppio (doublettes) o in triplo (triplettes). Le abilità individuali contano, ma le dinamiche di squadra possono fare la differenza. Le squadre migliori non sono sempre quelle più abili: sono quelle che lavorano meglio insieme.",-1)),u[3]||(u[3]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"La grande idea"),l("p",null,[l("strong",null,"I team migliori non sono sempre quelli più abili: sono quelli che lavorano meglio insieme."),s(" Essere umili, affamati ed emotivamente intelligenti ti rende un ottimo compagno di squadra.")])],-1)),(o(),r(c,null,{default:d(()=>[t(q,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BOttimo%20compagno%20di%20squadra%5D%20--%3E%20B%5BUmile%5D%0A%20%20%20%20A%20--%3E%20C%5BAffamato%5D%0A%20%20%20%20A%20--%3E%20D%5BAccorto%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BSuccesso%20di%20squadra%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BPrestazioni%20da%20campionato%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=n('<h2 id="cosa-rende-un-compagno-di-squadra-eccezionale" tabindex="-1">Cosa rende un compagno di squadra eccezionale? <a class="header-anchor" href="#cosa-rende-un-compagno-di-squadra-eccezionale" aria-label="Permalink to &quot;Cosa rende un compagno di squadra eccezionale?&quot;">​</a></h2><p>La ricerca e l&#39;esperienza evidenziano tre qualità fondamentali:</p><h3 id="_1-umile" tabindex="-1">1. Umile <a class="header-anchor" href="#_1-umile" aria-label="Permalink to &quot;1. Umile&quot;">​</a></h3><ul><li>Dà priorità al successo della squadra rispetto alla gloria personale</li><li>Riconosce i contributi degli altri</li><li>Ammette gli errori senza scuse</li><li>Aperto al feedback e all&#39;apprendimento</li><li>Non deve essere la star</li></ul><h3 id="_2-affamato" tabindex="-1">2. Affamato <a class="header-anchor" href="#_2-affamato" aria-label="Permalink to &quot;2. Affamato&quot;">​</a></h3><ul><li>Auto-motivato e determinato</li><li>Fa il lavoro senza che gli venga chiesto</li><li>Sempre alla ricerca di migliorare</li><li>Porta energia alla squadra</li><li>Non si affida al talento</li></ul><h3 id="_3-intelligente-emotivamente" tabindex="-1">3. Intelligente (emotivamente) <a class="header-anchor" href="#_3-intelligente-emotivamente" aria-label="Permalink to &quot;3. Intelligente (emotivamente)&quot;">​</a></h3><ul><li>Legge bene le situazioni e le persone</li><li>Sa quando parlare e quando ascoltare</li><li>Gestisce le proprie emozioni</li><li>Supporta i compagni di squadra in modo appropriato</li><li>Gestisce i conflitti in modo costruttivo</li></ul><h2 id="le-basi-del-successo-di-squadra" tabindex="-1">Le basi del successo di squadra <a class="header-anchor" href="#le-basi-del-successo-di-squadra" aria-label="Permalink to &quot;Le basi del successo di squadra&quot;">​</a></h2><h3 id="obiettivi-e-visione-condivisi" tabindex="-1">Obiettivi e visione condivisi <a class="header-anchor" href="#obiettivi-e-visione-condivisi" aria-label="Permalink to &quot;Obiettivi e visione condivisi&quot;">​</a></h3><p>Le squadre forti hanno:</p><ul><li>Obiettivi chiari e concordati</li><li>Obiettivi individuali allineati con gli obiettivi di squadra</li><li>Comprensione condivisa di cosa significhi il successo</li><li>Impegno per la missione collettiva</li></ul><p><strong>Domande da discutere con il tuo team:</strong></p><ul><li>Cosa stiamo cercando di realizzare insieme?</li><li>Come si manifesta il successo per noi?</li><li>In che modo i nostri obiettivi individuali supportano il team?</li></ul><h3 id="comunicazione-efficace" tabindex="-1">Comunicazione efficace <a class="header-anchor" href="#comunicazione-efficace" aria-label="Permalink to &quot;Comunicazione efficace&quot;">​</a></h3><p>La comunicazione è la linfa vitale delle prestazioni di squadra.</p><p><strong>Buona comunicazione di squadra:</strong></p><ul><li>Aperto e onesto</li><li>Rispettoso, anche nel disaccordo</li><li>Chiaro e specifico</li><li>Bidirezionale (parlare E ascoltare)</li><li>Tempestivo (informazioni giuste al momento giusto)</li></ul>',18)),t(b),u[5]||(u[5]=n('<p><strong>Durante le partite:</strong></p><ul><li>Discutere la strategia prima di ogni fine</li><li>Condividi osservazioni sul terreno, sugli avversari</li><li>Coordinare chi lancia quando</li><li>Sostenetevi a vicenda dopo i lanci (buoni o cattivi)</li></ul><h3 id="fiducia-e-rispetto" tabindex="-1">Fiducia e rispetto <a class="header-anchor" href="#fiducia-e-rispetto" aria-label="Permalink to &quot;Fiducia e rispetto&quot;">​</a></h3><p>Senza fiducia, i team si disgregano sotto pressione.</p><p><strong>Creare fiducia:</strong></p><ul><li>Sii affidabile (fai quello che dici)</li><li>Sii competente (fai bene il tuo lavoro)</li><li>Sii onesto (anche quando è difficile)</li><li>Mostrare vulnerabilità (ammettere le difficoltà)</li><li>Supportare gli altri in modo coerente</li></ul><p><strong>Mostrare rispetto:</strong></p><ul><li>Valorizzare il contributo di ogni persona</li><li>Ascolta diverse prospettive</li><li>Riconoscere lo sforzo, non solo i risultati</li><li>Considerare importante il ruolo di tutti</li></ul><h3 id="ruoli-chiari" tabindex="-1">Ruoli chiari <a class="header-anchor" href="#ruoli-chiari" aria-label="Permalink to &quot;Ruoli chiari&quot;">​</a></h3><p>Tutti dovrebbero capire:</p><ul><li>Le loro responsabilità principali</li><li>Come contribuiscono alla squadra</li><li>Ciò per cui gli altri contano su di loro</li><li>Quando fare un passo avanti e quando fare un passo indietro</li></ul><p><strong>In triplette:</strong></p><table tabindex="0"><thead><tr><th>Ruolo</th><th>Focus primario</th><th>Qualità chiave</th></tr></thead><tbody><tr><td>Puntatore</td><td>Posizionare le bocce vicino al jack</td><td>Precisione, coerenza</td></tr><tr><td>Mezzo</td><td>Adattarsi alla situazione</td><td>Versatilità, gioco di lettura</td></tr><tr><td>Tiratore</td><td>Rimuovi le bocce dell&#39;avversario</td><td>Precisione sotto pressione</td></tr></tbody></table><p>I ruoli possono essere flessibili, ma la chiarezza aiuta.</p><h2 id="dinamiche-di-squadra-durante-la-competizione" tabindex="-1">Dinamiche di squadra durante la competizione <a class="header-anchor" href="#dinamiche-di-squadra-durante-la-competizione" aria-label="Permalink to &quot;Dinamiche di squadra durante la competizione&quot;">​</a></h2><h3 id="prima-della-partita" tabindex="-1">Prima della partita <a class="header-anchor" href="#prima-della-partita" aria-label="Permalink to &quot;Prima della partita&quot;">​</a></h3><ul><li>Arrivare insieme, riscaldarsi insieme</li><li>Discutere la strategia generale</li><li>Imposta il tono (positivo, concentrato)</li><li>Controlla come si sente ognuno</li></ul><h3 id="durante-il-gioco" tabindex="-1">Durante il gioco <a class="header-anchor" href="#durante-il-gioco" aria-label="Permalink to &quot;Durante il gioco&quot;">​</a></h3><ul><li>Comunicare tra le estremità</li><li>Rimani positivo indipendentemente dal punteggio</li><li>Sostenersi a vicenda dopo gli errori</li><li>Festeggiamo insieme i successi (brevemente)</li><li>Concentrati sul processo, non sul risultato</li></ul><h3 id="dopo-gli-errori" tabindex="-1">Dopo gli errori <a class="header-anchor" href="#dopo-gli-errori" aria-label="Permalink to &quot;Dopo gli errori&quot;">​</a></h3><p>Cosa NON fare:</p><ul><li>Mostrare visibilmente la frustrazione</li><li>Criticare o incolpare</li><li>Ritirarsi o tacere</li><li>Soffermati su ciò che è successo</li></ul><p>Cosa fare:</p><ul><li>Riconoscimento rapido (&quot;nessun problema&quot;)</li><li>Sposta l&#39;attenzione sul lancio successivo</li><li>Mantenere un linguaggio del corpo positivo</li><li>Fidati del tuo compagno di squadra per riprendersi</li></ul><h3 id="dopo-la-partita" tabindex="-1">Dopo la partita <a class="header-anchor" href="#dopo-la-partita" aria-label="Permalink to &quot;Dopo la partita&quot;">​</a></h3><ul><li>Fare un debriefing insieme (cosa ha funzionato, cosa no)</li><li>Riconoscere i contributi individuali</li><li>Discutere i miglioramenti per la prossima volta</li><li>Mantenere le relazioni indipendentemente dal risultato</li></ul><h2 id="modelli-di-comunicazione" tabindex="-1">Modelli di comunicazione <a class="header-anchor" href="#modelli-di-comunicazione" aria-label="Permalink to &quot;Modelli di comunicazione&quot;">​</a></h2><h3 id="feedback-costruttivo" tabindex="-1">Feedback costruttivo <a class="header-anchor" href="#feedback-costruttivo" aria-label="Permalink to &quot;Feedback costruttivo&quot;">​</a></h3><p><strong>Povero:</strong> &quot;Continui a sbagliare quei tiri&quot; <strong>Meglio:</strong> &quot;Ho notato che i tiri vanno verso sinistra: vuoi provare a modificare la tua posizione?&quot;</p><h3 id="risposta-di-supporto-agli-errori" tabindex="-1">Risposta di supporto agli errori <a class="header-anchor" href="#risposta-di-supporto-agli-errori" aria-label="Permalink to &quot;Risposta di supporto agli errori&quot;">​</a></h3><p><strong>Scarso:</strong> <em>Silenzio o frustrazione visibile</em><strong>Meglio:</strong> &quot;Difficile. Hai già la prossima.&quot;</p><h3 id="discussione-strategica" tabindex="-1">Discussione strategica <a class="header-anchor" href="#discussione-strategica" aria-label="Permalink to &quot;Discussione strategica&quot;">​</a></h3><p><strong>Povero:</strong> &quot;Spara e basta&quot; <strong>Meglio:</strong> &quot;Cosa ne pensi: puntare per bloccare o provare a tirare? Vedo pro e contro in entrambi i casi.&quot;</p><h2 id="costruire-una-cultura-di-squadra" tabindex="-1">Costruire una cultura di squadra <a class="header-anchor" href="#costruire-una-cultura-di-squadra" aria-label="Permalink to &quot;Costruire una cultura di squadra&quot;">​</a></h2><p>I grandi team sviluppano in modo condiviso:</p><ul><li><strong>Valori:</strong> Ciò che rappresentiamo</li><li><strong>Norme:</strong> Come ci comportiamo</li><li><strong>Lingua:</strong> Come comunichiamo</li><li><strong>Rituali:</strong> Cosa facciamo insieme</li></ul><p><strong>Esempi:</strong></p><ul><li>Stringetevi sempre la mano prima e dopo</li><li>Frasi di incoraggiamento specifiche</li><li>Routine pre-partita insieme</li><li>Pasto o bevanda dopo la partita</li></ul><h2 id="in-questa-sezione" tabindex="-1">In questa sezione <a class="header-anchor" href="#in-questa-sezione" aria-label="Permalink to &quot;In questa sezione&quot;">​</a></h2><ul><li><strong><a href="/it/education/team-player/communication">Comunicazione di squadra</a></strong> - Guida dettagliata per comunicare in modo efficace</li></ul><h2 id="conclusione-chiave" tabindex="-1">Conclusione chiave <a class="header-anchor" href="#conclusione-chiave" aria-label="Permalink to &quot;Conclusione chiave&quot;">​</a></h2><blockquote><p>La forza della tua squadra è data solo dalla sua relazione più debole, non dal suo giocatore più debole.</p></blockquote><p>Investi nei tuoi compagni di squadra. Costruisci fiducia. Comunica bene. Vinci insieme.</p>',43)),t(f)])}]]);export{u as __pageData,p as default};
